/* Phase 27: permission-checked generic vendor USB API policy. No user pointer is DMAed directly. */
#pragma once
#include "ehci_spec.hpp"
namespace starlix::drivers::ehci::vendor_api_policy {
constexpr uint8_t kVendorInterfaceClass=0xFFu;
constexpr uint32_t kMaxTransferBytes=16384u,kMaxAllowlistEntries=16u,kMaxPipes=8u;
enum Capability:uint32_t{ControlIn=1u<<0u,ControlOut=1u<<1u,BulkIn=1u<<2u,BulkOut=1u<<3u};
constexpr uint32_t kKnownCapabilities=ControlIn|ControlOut|BulkIn|BulkOut;
enum class TransferKind:uint8_t{Control=0u,Bulk=1u,Interrupt=2u,Isochronous=3u};
struct AllowEntry{uint16_t vendor_id;uint16_t product_id;uint8_t interface_number;uint32_t capabilities;uint32_t max_transfer;};
struct AllowList{AllowEntry entries[kMaxAllowlistEntries];uint8_t count;};
struct Handle{uint8_t address;uint8_t interface_number;uint32_t generation;uint32_t token;};
struct Request{bool interface_class_is_vendor;bool device_allowlisted;bool interface_claimed;bool user_buffer_validated_and_bounced;uint32_t device_generation;uint32_t current_generation;uint32_t allowlisted_capabilities;uint32_t max_allowed_transfer;uint32_t capability;TransferKind kind;uint8_t endpoint_address;uint8_t control_bm_request_type;uint16_t length;uint16_t max_packet;};
inline void allowlist_init(AllowList* l){if(!l)return;l->count=0u;for(uint32_t i=0;i<kMaxAllowlistEntries;++i)l->entries[i]={0u,0u,0u,0u,0u};}
inline bool allowlist_add(AllowList*l,uint16_t vid,uint16_t pid,uint8_t iface,uint32_t caps,uint32_t max_transfer){if(!l||l->count>=kMaxAllowlistEntries||vid==0u||pid==0u||caps==0u||(caps&~kKnownCapabilities)!=0u||max_transfer==0u||max_transfer>kMaxTransferBytes)return false;for(uint32_t i=0;i<l->count;++i)if(l->entries[i].vendor_id==vid&&l->entries[i].product_id==pid&&l->entries[i].interface_number==iface)return false;l->entries[l->count++]={vid,pid,iface,caps,max_transfer};return true;}
inline bool is_allowlisted(const AllowList*l,uint16_t vid,uint16_t pid,uint8_t iface,uint32_t* caps,uint32_t* max_transfer){if(caps)*caps=0u;if(max_transfer)*max_transfer=0u;if(!l||!caps||!max_transfer)return false;for(uint32_t i=0;i<l->count;++i){const auto&e=l->entries[i];if(e.vendor_id==vid&&e.product_id==pid&&e.interface_number==iface){*caps=e.capabilities;*max_transfer=e.max_transfer;return true;}}return false;}
constexpr bool valid_handle(const Handle&h,uint8_t expected_address,uint8_t expected_iface,uint32_t current_generation,uint32_t expected_token){return h.address>0u&&h.address<128u&&h.address==expected_address&&h.interface_number==expected_iface&&h.generation!=0u&&h.generation==current_generation&&h.token!=0u&&h.token==expected_token;}
constexpr bool request_allowed(const Request&r){if(!r.interface_class_is_vendor||!r.device_allowlisted||!r.interface_claimed||!r.user_buffer_validated_and_bounced||r.device_generation==0u||r.device_generation!=r.current_generation||r.length==0u||r.length>kMaxTransferBytes||r.max_packet==0u||r.max_allowed_transfer==0u||r.max_allowed_transfer>kMaxTransferBytes||r.length>r.max_allowed_transfer||r.capability==0u||(r.capability&(r.capability-1u))!=0u||(r.allowlisted_capabilities&r.capability)==0u)return false;
 if(r.kind==TransferKind::Control){if(r.capability!=ControlIn&&r.capability!=ControlOut)return false;if((r.control_bm_request_type&0x60u)!=0x40u||(r.control_bm_request_type&0x1Fu)>2u)return false;const bool in=(r.control_bm_request_type&0x80u)!=0u;if(in!=(r.capability==ControlIn))return false;return true;}
 if(r.kind==TransferKind::Bulk){if(r.control_bm_request_type!=0u)return false;if(r.capability!=BulkIn&&r.capability!=BulkOut)return false;if((r.endpoint_address&0x0Fu)==0u)return false;const bool in=(r.endpoint_address&0x80u)!=0u;if(in!=(r.capability==BulkIn))return false;if(r.max_packet>512u)return false;return true;}
 /* Interrupt/isochronous user pipes are intentionally not exposed until their lifetime models are hardened. */
 return false;}
constexpr bool self_test(){AllowList list{};allowlist_init(&list);if(!allowlist_add(&list,0x1234u,0x5678u,2u,ControlIn|ControlOut|BulkIn|BulkOut,4096u))return false;if(allowlist_add(&list,0x1234u,0x5678u,2u,BulkIn,128u))return false;uint32_t caps=0u,max=0u;if(!is_allowlisted(&list,0x1234u,0x5678u,2u,&caps,&max)||caps!=(ControlIn|ControlOut|BulkIn|BulkOut)||max!=4096u||is_allowlisted(&list,0xDEADu,1u,2u,&caps,&max))return false;
 const Handle h{4u,2u,7u,0xA55Au};if(!valid_handle(h,4u,2u,7u,0xA55Au)||valid_handle(h,4u,2u,8u,0xA55Au)||valid_handle(h,4u,2u,7u,0x1234u))return false;
 Request r{true,true,true,true,7u,7u,kKnownCapabilities,4096u,BulkIn,TransferKind::Bulk,0x81u,0u,512u,512u};if(!request_allowed(r))return false;r.current_generation=8u;if(request_allowed(r))return false;r.current_generation=7u;r.user_buffer_validated_and_bounced=false;if(request_allowed(r))return false;r.user_buffer_validated_and_bounced=true;r.endpoint_address=0x01u;if(request_allowed(r))return false;r.endpoint_address=0x81u;r.kind=TransferKind::Interrupt;if(request_allowed(r))return false;r.kind=TransferKind::Control;r.capability=ControlIn;r.control_bm_request_type=0x80u;if(request_allowed(r))return false;r.control_bm_request_type=0xC0u;if(!request_allowed(r))return false;r.control_bm_request_type=0x80u;r.length=0u;if(request_allowed(r))return false;r.length=5000u;if(request_allowed(r))return false;r.length=32u;r.max_allowed_transfer=16u;if(request_allowed(r))return false;r.max_allowed_transfer=4096u;r.allowlisted_capabilities=BulkOut;if(request_allowed(r))return false;r.allowlisted_capabilities=kKnownCapabilities;r.device_allowlisted=false;if(request_allowed(r))return false;return true;}
} // namespace starlix::drivers::ehci::vendor_api_policy
